(()=>{'use strict';const query=document.querySelector('[data-pmx-query]'),family=document.querySelector('[data-pmx-family]'),format=document.querySelector('[data-pmx-format]');if(!query)return;const cards=[...document.querySelectorAll('[data-pmx-product]')],count=document.querySelector('[data-pmx-count]'),empty=document.querySelector('[data-pmx-empty]');function apply(){const term=query.value.trim().toLocaleLowerCase();let n=0;for(const card of cards){const yes=(!term||card.dataset.search.includes(term))&&(family.value==='all'||card.dataset.family===family.value)&&(format.value==='all'||card.dataset.format===format.value);card.hidden=!yes;if(yes)n++}count.textContent=n+' of '+cards.length+' profiles';empty.hidden=n!==0;}query.addEventListener('input',apply);family.addEventListener('change',apply);format.addEventListener('change',apply);apply();})();